// ===== Hash 路由：监听 hashchange，# 后内容不发服务器 =====
class HashRouter {
  constructor() {
    this.routes = {};
    // hashchange 在编程式修改和前进后退时都会触发
    window.addEventListener('hashchange', () => this.resolve());
    // 首次加载时 hash 已经存在，需要主动匹配
    window.addEventListener('load', () => this.resolve());
  }

  route(path, callback) {
    this.routes[path] = callback;
  }

  resolve() {
    // 从 hash 中提取路径，去掉 # 前缀
    const hash = window.location.hash.slice(1) || '/';
    const handler = this.routes[hash];
    if (handler) handler();
    else if (this.routes['*']) this.routes['*']();
  }

  navigate(path) {
    window.location.hash = path; // 触发 hashchange
  }
}

// ===== History 路由：pushState 不触发 popstate，需手动调用 resolve =====
class HistoryRouter {
  constructor() {
    this.routes = {};
    // popstate 只在浏览器前进后退时触发
    window.addEventListener('popstate', () => this.resolve());
  }

  route(path, callback) {
    this.routes[path] = callback;
  }

  resolve() {
    const path = window.location.pathname;
    const handler = this.routes[path];
    if (handler) handler();
    else if (this.routes['*']) this.routes['*']();
  }

  navigate(path, state = null) {
    // pushState 不触发 popstate，必须手动调用 resolve
    window.history.pushState(state, '', path);
    this.resolve();
  }
}

// ===== React 路由懒加载 + 守卫示例 =====
import { lazy, Suspense } from 'react';
import { Route, Navigate, useLocation } from 'react-router-dom';

// 每个路由组件只在访问时才加载对应 chunk
const Home = lazy(() => import('./pages/Home'));
const Dashboard = lazy(() => import('./pages/Dashboard'));

// 路由守卫：未登录则重定向到登录页
function PrivateRoute({ children }) {
  const isAuth = useAuth();
  const location = useLocation();
  if (!isAuth) {
    // 保存来源路径，登录后可以跳回
    return <Navigate to="/login" state={{ from: location }} replace />;
  }
  return children;
}

// App 路由配置
function App() {
  return (
    <Suspense fallback={<div>Loading...</div>}>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/dashboard" element={
          <PrivateRoute>
            <Dashboard />
          </PrivateRoute>
        } />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </Suspense>
  );
}

# Nginx：History 模式必须配置的回退
server {
    listen 80;
    server_name example.com;
    root /var/www/dist;

    location / {
        # 先尝试匹配静态文件，找不到就返回 index.html
        try_files $uri $uri/ /index.html;
    }
}

# Node.js / Express
const express = require('express');
const path = require('path');
const app = express();

// 先处理静态资源
app.use(express.static('dist'));

// 所有其他请求回退到 index.html
app.get('*', (req, res) => {
    res.sendFile(path.join(__dirname, 'dist/index.html'));
});

app.listen(3000);
